/**
 * What Pro did for the learner during the trial (`GET /billing/trial/facts`),
 * for the Plan page and Today's week card. Like the plan itself it is the
 * server's answer and is fetched, never stored: it is read when a screen
 * that shows it opens, kept in memory for the run of the app (at most
 * `FACTS_FRESH_MS` old), and forgotten when another account signs in.
 */
import { create } from 'zustand';
import { billing as billingApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import type { ApiTrialFacts } from '@/api/types.js';
import { t } from '@/i18n/index.js';

/**
 * How long one answer is shown before a screen that opens asks again. The
 * counts move only as the learner uses Pro, so a few minutes is plenty; a
 * client-side guard against asking on every render, not a business value.
 */
export const FACTS_FRESH_MS = 5 * 60_000;

export type FactsStatus = 'idle' | 'loading' | 'ok' | 'none' | 'failed';

interface FactsState {
  facts: ApiTrialFacts | null;
  status: FactsStatus;
  at: number;
  /** Reads the facts unless a fresh answer is in hand. */
  ensure: () => void;
  forget: () => void;
}

let generation = 0;

export const useTrialFacts = create<FactsState>((set, get) => ({
  facts: null,
  status: 'idle',
  at: 0,
  ensure() {
    const { status, at } = get();
    if (status === 'loading') return;
    if ((status === 'ok' || status === 'none') && Date.now() - at < FACTS_FRESH_MS) return;
    const asked = generation;
    set({ status: 'loading' });
    billingApi
      .trialFacts()
      .then((facts) => {
        if (asked === generation) set({ facts, status: 'ok', at: Date.now() });
      })
      .catch((cause: unknown) => {
        if (asked !== generation) return;
        // 404: the account never had a trial, which is nothing to show.
        if (isApiError(cause, 'notFound')) set({ facts: null, status: 'none', at: Date.now() });
        else set({ status: 'failed' });
      });
  },
  forget() {
    generation += 1;
    set({ facts: null, status: 'idle', at: 0 });
  },
}));

/** A count from the server, or zero for anything that is not a sensible one. */
function count(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? Math.floor(value) : 0;
}

/**
 * The lines "What Pro did for you" says: one per count that is not zero,
 * in a fixed order. Nothing estimated, nothing for a zero.
 */
export function factLines(facts: ApiTrialFacts | null): string[] {
  if (facts === null) return [];
  const lines: string[] = [];
  const lex = count(facts.lexQuestions);
  const cards = count(facts.aiCards);
  const texts = count(facts.textsSearched);
  const notebooks = count(facts.extraNotebooks);
  if (lex > 0) lines.push(t('plan.facts.lex', { count: lex }));
  if (cards > 0) lines.push(t('plan.facts.aiCards', { count: cards }));
  if (texts > 0) lines.push(t('plan.facts.texts', { count: texts }));
  if (notebooks > 0) lines.push(t('plan.facts.notebooks', { count: notebooks }));
  return lines;
}
