/**
 * What this account is on, and what it may buy.
 *
 * This is the one thing the app reads from the network rather than from
 * IndexedDB. A plan is not the learner's data: it is the server's answer
 * about money, it changes without this device doing anything, and a stale
 * copy would either show a paywall to someone who has paid or hide one from
 * someone who has not. So it is fetched, never stored.
 */
import { create } from 'zustand';
import { billing as billingApi } from '@/api/endpoints.js';
import type { ApiBillingState } from '@/api/types.js';
import { heldPurchases, onAndroid, onIOS } from './play.js';
import {
  listenForTransactions,
  loadStoreProducts,
  restoreAppStore,
  storeProductsNow,
  type StoreProduct,
} from './appstore.js';
import { platform } from '@/lib/platform/index.js';
import { useTrialFacts } from './facts.js';
import { getLocale } from '@/i18n/index.js';
import { noteServerTime } from '@/lib/serverClock.js';

/** The plan an account is on. */
export type Plan = 'free' | 'pro';

/**
 * One price as a screen shows it. In the iPhone app it comes from the App
 * Store rather than the server: `display` is Apple's own formatted price for
 * this Apple Account's storefront and `title` the subscription's name in App
 * Store Connect, and they win over anything worked out here.
 */
export type PlanPrice = ApiBillingState['prices'][number] & {
  display?: string;
  title?: string;
  /** The BCP 47 locale Apple formats this storefront's prices in. */
  locale?: string;
};

interface BillingState {
  /** Null until the first answer arrives, or if it never does. */
  state: ApiBillingState | null;
  loading: boolean;
  /**
   * Whether an answer, or a failure, has come back at least once. A screen
   * that waits for the plan before drawing something (Today's trial
   * moments) stops waiting here, so a dropped request leaves it quiet
   * rather than waiting for ever.
   */
  checked: boolean;
  /** Reads the plan again. Called on mount and after a checkout closes. */
  refresh: () => Promise<void>;
  /**
   * Reads the plan if it is not known yet. Settings asks outright, because
   * it shows the plan; every other screen that might offer Pro asks this
   * instead, so opening one costs a call only the first time.
   */
  ensure: () => void;
  /**
   * Waits for the plan to become Pro after a payment, and reports whether it
   * did. The provider tells the server in its own time, so a payment that
   * has clearly gone through can still take a moment to show.
   */
  waitForPro: (attempts?: number) => Promise<boolean>;
  /** Replaces the plan with one the server has just answered with. */
  apply: (next: ApiBillingState) => void;
  /**
   * Forgets the plan, for a change of account in this tab: the next account
   * must never be shown the last one's plan, trial or prices, and an answer
   * still on its way for the last one is dropped when it lands.
   */
  forget: () => void;
  /** The account the plan in hand belongs to, once one has signed in. */
  owner: string | undefined;
  /**
   * Says which account is signed in: a different one than the plan belongs
   * to forgets the plan first. Answers whether it did.
   */
  belongsTo: (accountId: string) => boolean;
  /**
   * Sends every Google Play purchase this device holds to the server, so a
   * reinstall, a new phone or a purchase that finished while the app was
   * closed all end up as the plan they paid for. It does nothing anywhere
   * but Android, and nothing at all when there is nothing to send.
   */
  restorePlayPurchases: () => Promise<void>;
  /**
   * The iPhone app's twin of `restorePlayPurchases`: sends every App Store
   * transaction the device holds unfinished, and the subscriptions it is
   * entitled to, to the server, quietly (never the Apple Account sheet).
   * Nothing anywhere but iOS, and nothing while the iPhone app is not
   * selling.
   */
  restoreAppStorePurchases: () => Promise<void>;
  /**
   * "Don't remind me" (or reminders back on), saved on the account; the
   * plan in hand follows at once, so Today's cards go without a reload.
   * Throws what the server said.
   */
  setReminders: (remind: boolean) => Promise<void>;
}

/** Keeps the server's answer for Today's cold start; best effort, never awaited. */
function keepSnapshot(owner: string | undefined, answer: ApiBillingState): void {
  void import('./planSnapshot.js')
    .then((snapshot) => snapshot.notePlanSnapshot(owner, answer))
    .catch(() => undefined);
}

/** Bumped by `forget`, so an answer for an account that has gone is not applied. */
let generation = 0;

export const useBilling = create<BillingState>((set, get) => ({
  state: null,
  loading: false,
  checked: false,

  /**
   * Replaces the plan with one the server has just answered with, for the
   * calls that return the whole state rather than a confirmation. It saves
   * a second read of something we were just told.
   */
  apply(next: ApiBillingState) {
    set({ state: shown(next, storeProductsNow()), loading: false, checked: true });
    keepSnapshot(get().owner, next);
    // An answer that switches iPhone selling on before StoreKit has been
    // asked: ask now, and put Apple's prices in once they arrive.
    if (onIOS() && next.selling.ios === true && storeProductsNow().length === 0) {
      const asked = generation;
      void loadStoreProducts().then((found) => {
        const now = get().state;
        if (asked !== generation || found.length === 0 || now === null) return;
        set({ state: shown(now, found) });
      });
    }
  },

  owner: undefined,

  forget() {
    generation += 1;
    set({ state: null, loading: false, checked: false });
    // What Pro did for the last account is the last account's too.
    useTrialFacts.getState().forget();
  },

  belongsTo(accountId) {
    const { owner } = get();
    if (owner === accountId) return false;
    if (owner !== undefined) get().forget();
    set({ owner: accountId });
    return owner !== undefined;
  },

  ensure() {
    const { state, loading } = get();
    if (state !== null || loading) return;
    void get().refresh();
  },

  async refresh() {
    const asked = generation;
    set({ loading: true });
    try {
      const sent = performance.now();
      const answer = await billingApi.state(getLocale());
      // The server's clock, for counting down to its deadlines (skew-safe).
      noteServerTime(answer.serverNow, performance.now() - sent);
      // A live campaign's pictures, kept for offline (and pruned after it).
      void import('./campaignAssets.js')
        .then((assets) => assets.keepCampaignAssets(answer))
        .catch(() => undefined);
      // In the iPhone app the prices are Apple's, so the plan is not shown
      // until StoreKit has said what they are: a server price there would
      // be a number Apple does not charge.
      const products = onIOS() && answer.selling.ios === true ? await loadStoreProducts() : [];
      if (asked !== generation) return;
      set({ state: shown(answer, products), loading: false, checked: true });
      keepSnapshot(get().owner, answer);
    } catch {
      if (asked !== generation) return;
      // A failure leaves whatever was known before. The paywall simply does
      // not appear, which is the right way to fail: never show a price we
      // are not sure about, and never take Pro away over a dropped request.
      set({ loading: false, checked: true });
    }
  },

  async restorePlayPurchases() {
    if (!onAndroid()) return;
    const tokens = await heldPurchases();
    if (tokens.length === 0) return;
    for (const token of tokens) {
      try {
        // The answer is the plan itself, so the last one to arrive is the
        // state, and no extra read is needed.
        get().apply(await billingApi.verifyGooglePurchase(token));
      } catch {
        // A token Google no longer honours, or a network that is not there.
        // Neither is worth telling anybody about: nothing was bought just
        // now, and the next time the screen opens it tries again.
      }
    }
  },

  async restoreAppStorePurchases() {
    if (!onIOS() || get().state?.selling.ios !== true) return;
    const asked = generation;
    const result = await restoreAppStore({ sync: false });
    // Anything but a plan is not worth telling anybody about: nothing was
    // bought just now, and the next time the plan opens it tries again.
    if (result.kind === 'restored' && asked === generation) get().apply(result.state);
  },

  async setReminders(remind) {
    const asked = generation;
    const answer = await billingApi.setOfferReminders(remind);
    const now = get().state;
    if (asked !== generation || now === null) return;
    set({ state: withReminders(now, answer.remind) });
    // Back on: whether Today may speak again is the server's to say.
    if (answer.remind) void get().refresh();
  },

  async waitForPro(attempts = WAIT_ATTEMPTS) {
    for (let attempt = 0; attempt < attempts; attempt += 1) {
      await get().refresh();
      if (get().state?.plan === 'pro') return true;
      await pause(WAIT_GAP_MS);
    }
    return false;
  },
}));

/**
 * The plan with the learner's reminder choice applied the way the server
 * applies it: off also stops Today's day-by-day touches (`touches`), which
 * the server sends only while reminders are on.
 */
export function withReminders(state: ApiBillingState, remind: boolean): ApiBillingState {
  const next: ApiBillingState = { ...state, offerReminders: remind };
  if (!remind) {
    if (next.trial !== undefined) next.trial = { ...next.trial, touches: false };
    if (next.trialEnded !== undefined) next.trialEnded = { ...next.trialEnded, touches: false };
  }
  return next;
}

/**
 * How long to wait for the plan to catch up after a payment. The provider
 * tells the server in its own time, which is normally a second or two; this
 * is generous enough to cover a slow one without leaving anybody staring.
 */
const WAIT_ATTEMPTS = 10;
const WAIT_GAP_MS = 1500;

const pause = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * The plan as this client shows it. Everywhere but the iPhone app that is
 * exactly the server's answer. In the iPhone app the server's prices are
 * replaced by the App Store's, because Apple charges in the Apple Account's
 * own storefront and currency: never the server's USD, and nothing at all
 * while the iPhone app is not selling or StoreKit has no product to sell.
 */
function shown(answer: ApiBillingState, products: readonly StoreProduct[]): ApiBillingState {
  if (!onIOS()) return answer;
  return { ...answer, prices: answer.selling.ios === true ? storePrices(products) : [] };
}

/**
 * Apple's products as prices, in the plans' own order. A product whose
 * period is not the plan's (a month, a year) or whose price cannot be read
 * is left out rather than shown wrong.
 */
export function storePrices(products: readonly StoreProduct[]): PlanPrice[] {
  const periods = { pro_monthly: 'month', pro_yearly: 'year' } as const;
  return (['pro_monthly', 'pro_yearly'] as const).flatMap((id): PlanPrice[] => {
    const product = products.find((one) => one.id === id);
    if (product === undefined) return [];
    const period = product.period.value === 1 ? product.period.unit : undefined;
    if (period !== periods[id]) return [];
    const amount = Number(product.price);
    if (!Number.isFinite(amount) || amount <= 0 || product.currencyCode === '') return [];
    const locale = bcp47(product.priceLocale);
    return [
      {
        id,
        amountMinor: Math.round(amount * 10 ** currencyDigits(product.currencyCode)),
        currency: product.currencyCode,
        period: periods[id],
        display: product.displayPrice,
        ...(product.displayName === '' ? {} : { title: product.displayName }),
        ...(locale === undefined ? {} : { locale }),
      },
    ];
  });
}

/**
 * Apple's locale identifier ("de_DE", "en_US@currency=EUR") as a BCP 47 tag
 * Intl accepts ("de-DE"), or undefined when Intl does not know it.
 */
function bcp47(identifier: string | undefined): string | undefined {
  const tag = identifier?.split('@')[0]?.replaceAll('_', '-');
  if (tag === undefined || tag === '') return undefined;
  try {
    return Intl.NumberFormat.supportedLocalesOf([tag]).length > 0 ? tag : undefined;
  } catch {
    return undefined;
  }
}

/**
 * How many minor units a currency has: 2 for euros, 0 for yen, 3 for
 * dinars. Intl knows; an unknown code is treated as 2.
 */
function currencyDigits(currency: string): number {
  try {
    return (
      new Intl.NumberFormat('en', { style: 'currency', currency }).resolvedOptions().maximumFractionDigits ??
      2
    );
  } catch {
    return 2;
  }
}

/**
 * Starts listening for App Store transactions that arrive on their own (a
 * renewal, an approved Ask to Buy, last launch's unfinished ones), each sent
 * to the server and its plan applied here. Started once a session is ready
 * in the iPhone app; the returned stop is for signing out.
 */
export function listenForAppStore(): () => void {
  return listenForTransactions((state) => {
    useBilling.getState().apply(state);
  });
}

/** The plan, treating "we do not know yet" as free. */
export function planOf(state: ApiBillingState | null): Plan {
  return state?.plan === 'pro' ? 'pro' : 'free';
}

/**
 * Whether the account has already used a promotion. One per account, ever,
 * so a screen that knows this stops offering the way in rather than offering
 * something the server will refuse. Unknown reads as "not yet": the row is
 * worth showing while a plan is still loading, and the refusal is honest if
 * that turns out to be wrong.
 */
export function usedAPromo(state: ApiBillingState | null): boolean {
  return state?.promoUsed === true;
}

/**
 * Whether the app can offer to cancel or change a card from in here. Never
 * in the iPhone app: the provider's portal is a page that also sells, and
 * Apple does not allow a way out of the app to another seller.
 */
export function canManage(state: ApiBillingState | null): boolean {
  return state?.canManage === true && !onIOS();
}

/**
 * Whether this is the iPhone app, the server has switched selling on there,
 * and the App Store has at least one of the plans to sell. The prices in
 * the iPhone app are only ever StoreKit's (see `shown`), so a price without
 * Apple's own display string means StoreKit was never asked and nothing is
 * sold.
 */
export function canBuyOnIOS(state: ApiBillingState | null): boolean {
  return (
    onIOS() &&
    state?.selling.ios === true &&
    paidPrices(state).some((one) => one.display !== undefined && one.display !== '')
  );
}

/** Whether this client may sell at all right now. */
export function canBuyOnWeb(state: ApiBillingState | null): boolean {
  return state?.selling.web === true;
}

/**
 * Whether this is the Android app and the server has switched selling on
 * there. The two switches are separate on purpose: a purchase made inside
 * the app must go through Google Play, never Paddle.
 */
export function canBuyOnAndroid(state: ApiBillingState | null): boolean {
  return state?.selling.android === true && onAndroid();
}

/**
 * Whether the paywall may be offered on this client at all. Never inside the
 * desktop app: its window loads nothing from Paddle and has no store of its
 * own, so it is a client that may not sell, and shows no price. Inside the
 * iPhone app only through Apple (`canBuyOnIOS`): Paddle there would break
 * the App Store's rules whatever the server says.
 */
export function canBuyHere(state: ApiBillingState | null): boolean {
  if (platform.desktop !== undefined) return false;
  if (onIOS()) return canBuyOnIOS(state);
  return onAndroid() ? canBuyOnAndroid(state) : canBuyOnWeb(state);
}

/**
 * Whether this plan is managed in Google Play. There is no portal of theirs
 * for us to open, so the app links to Play's own subscriptions screen
 * instead of asking the server for a link.
 */
export function managedInPlay(state: ApiBillingState | null): boolean {
  return state?.plan === 'pro' && state.provider === 'google_play' && !onIOS();
}

/**
 * Where somebody who bought in the app cancels or changes a card. Google
 * Play is the seller there, so it is the only place that can do either.
 */
export const PLAY_SUBSCRIPTIONS_URL = 'https://play.google.com/store/account/subscriptions';

/**
 * Whether this plan was bought in the App Store. Apple is the seller, so its
 * own sheet (in the iPhone app) or its subscriptions page (anywhere else) is
 * the only place to change or cancel it; the server's `canManage` is false
 * for it and there is no portal of ours.
 */
export function managedInAppStore(state: ApiBillingState | null): boolean {
  return state?.plan === 'pro' && state.provider === 'apple';
}

/** The two paid prices, or an empty list. */
export function paidPrices(state: ApiBillingState | null): PlanPrice[] {
  return (state?.prices ?? []).filter((price) => price.id !== 'free');
}

/**
 * Whether this notebook costs nothing to use whatever the account pays: a
 * notebook with a language from the server's free list on either side is
 * never counted against an allowance, and nobody reading one should be shown
 * a reason to pay. The server says which languages those are; this never
 * hard-codes them. The list is empty since 12 Oct 2026, when Persian joined
 * the same plans as every other language, so an empty list must make every
 * screen behave as for any other notebook, with no app update.
 */
export function freeNotebook(
  state: ApiBillingState | null,
  targetLang: string | undefined,
  meaningLang: string | undefined,
): boolean {
  return freeSide(state, targetLang, meaningLang) !== undefined;
}

/**
 * Whether an offer of Pro can honestly be made here at all.
 *
 * Every condition is a deliberate silence rather than an oversight: nobody
 * is sold what they already have, a client the server has not switched
 * selling on shows no price it cannot honour, a price we are unsure of is
 * worse than no offer, and a notebook Lexpad never charges for is never
 * shown a reason to pay.
 *
 * `ProOffer` renders exactly when this is true. It is exported so a screen
 * that locks something behind Pro can tell whether tapping it will produce
 * an offer or nothing at all, and say something either way, from the same
 * answer rather than from a second copy of these rules.
 */
export function offerable(
  state: ApiBillingState | null,
  targetLang: string | undefined,
  meaningLang: string | undefined,
): boolean {
  if (state === null || state.plan === 'pro') return false;
  if (!canBuyHere(state) || cheapestPrice(state) === undefined) return false;
  return !freeNotebook(state, targetLang, meaningLang);
}

/** The cheapest paid price, or nothing when there is none to show. */
export function cheapestPrice(state: ApiBillingState | null): PlanPrice | undefined {
  return paidPrices(state).reduce<PlanPrice | undefined>(
    (best, one) => (best === undefined || one.amountMinor < best.amountMinor ? one : best),
    undefined,
  );
}

/**
 * Whether a Pro feature is open in this notebook, right now, on this
 * account.
 *
 * Paying is one way in and the notebook is the other: the server exempts a
 * notebook Lexpad never charges for from every paid feature, not just from
 * the price, so a screen that asked only about the plan would lock
 * somebody out of something the API would have given them.
 *
 * A plan nobody has been able to read yet counts as open. The alternative
 * is locking a feature over a dropped request or a phone that is offline,
 * and for a feature that costs nothing to run — the microphone is the
 * device's own — that is the wrong way round. Anything that costs us money
 * per use is refused by the server anyway, which is the only refusal that
 * counts.
 */
export function proHere(
  state: ApiBillingState | null,
  targetLang: string | undefined,
  meaningLang: string | undefined,
): boolean {
  if (state === null) return true;
  return state.plan === 'pro' || freeNotebook(state, targetLang, meaningLang);
}

/**
 * Which side of the notebook is a language Lexpad never charges for, and
 * which one it is. The two sides deserve different words: somebody learning
 * the language is being given the thing they came for, while somebody
 * reading their meanings in it is who the app was built for.
 *
 * Both sides free resolves to the target, which is the stronger statement.
 * The codes come from the server (empty since 12 Oct 2026), so this stays
 * right whatever the list holds.
 */
export function freeSide(
  state: ApiBillingState | null,
  targetLang: string | undefined,
  meaningLang: string | undefined,
): { side: 'target' | 'meaning'; code: string } | undefined {
  const free = state?.freeLanguages ?? [];
  const match = (
    side: 'target' | 'meaning',
    code: string | undefined,
  ): { side: 'target' | 'meaning'; code: string } | undefined =>
    code !== undefined && free.some((one) => sameLanguage(one, code)) ? { side, code } : undefined;
  // The target side wins when both are free: being given the language you
  // came for is the stronger thing to say.
  return match('target', targetLang) ?? match('meaning', meaningLang);
}

/**
 * Whether moving a notebook to another pair of languages is part of Pro, the
 * way the server decides it (notebook_needs_pro on PATCH and on a sync
 * push): a notebook in a language Lexpad gives away is free however many the
 * account has, so moving one out of that language, while the owner keeps
 * another notebook, is making a new paid notebook. Every other change is
 * allowed, so a notebook somebody already keeps is never locked.
 *
 * Returns the free language being left when the change needs Pro, and
 * undefined when it may go ahead. An unknown plan allows it: the server has
 * the last word, and a paywall shown on a guess is worse than none.
 */
export function changeNeedsPro(
  state: ApiBillingState | null,
  otherOwned: number,
  from: { targetLang: string; meaningLang: string },
  to: { targetLang: string; meaningLang: string },
): string | undefined {
  if (state === null || state.plan === 'pro' || otherOwned === 0) return undefined;
  const left = freeSide(state, from.targetLang, from.meaningLang);
  if (left === undefined || freeSide(state, to.targetLang, to.meaningLang) !== undefined) return undefined;
  return left.code;
}

/**
 * Whether two language tags name the same language, the way the server
 * decides it: case does not matter and a region is ignored, so "pt-BR" is
 * Portuguese. The two have to agree, or a notebook the server charges nothing
 * for would still be shown a price.
 */
function sameLanguage(a: string, b: string): boolean {
  const primary = (code: string): string => code.split(/[-_]/)[0]?.toLowerCase() ?? '';
  return a !== '' && b !== '' && primary(a) === primary(b);
}

/**
 * An amount in minor units, as money: 499 USD becomes "$4.99", and 900 USD
 * becomes "$9" rather than "$9.00".
 *
 * A round price reads as a round price. Trailing zeroes make a number look
 * longer and more expensive than it is, and "$9.00" is a receipt where "$9"
 * is an offer. Cents are shown when there are cents to show.
 */
export function price(amountMinor: number, currency: string): string {
  const round = amountMinor % 100 === 0;
  const digits = round ? { minimumFractionDigits: 0, maximumFractionDigits: 0 } : {};
  try {
    return new Intl.NumberFormat(undefined, { style: 'currency', currency, ...digits }).format(
      amountMinor / 100,
    );
  } catch {
    // An unknown currency code is still worth showing a number for.
    return `${(amountMinor / 100).toFixed(round ? 0 : 2)} ${currency}`;
  }
}

/**
 * A plan's price as a screen shows it: Apple's own string in the iPhone app,
 * the server's amount formatted here everywhere else. Every place that
 * prints a plan's price goes through this, so the iPhone app never shows a
 * number Apple is not charging.
 */
export function formatPrice(p: PlanPrice): string {
  return p.display ?? price(p.amountMinor, p.currency);
}
