/**
 * Buying inside the iPhone app.
 *
 * Apple must be the seller there: App Store Review Guideline 3.1.1 allows
 * only its own in-app purchase for digital goods. So the same plan is bought
 * three ways — Paddle's overlay on the web, Google Play's sheet in the
 * Android app, Apple's sheet here — and all three end in the same place,
 * with the server deciding what was actually bought.
 *
 * Nothing in this file decides that anybody has paid. StoreKit hands back a
 * transaction id and Apple's signed copy of it; the server reads the
 * subscription back from Apple and answers with the plan. Only once it has
 * answered 200 is the transaction finished. One that is not finished is not
 * lost: StoreKit offers it again at every launch (`Transaction.updates`) and
 * whenever the plan is opened (`unfinished`), so a server that could not be
 * reached at the wrong moment is a wait, never somebody's lost money.
 *
 * The native side is `StoreKitPlugin.swift` in lexpad_ios, registered there
 * as `AppStore`.
 */
import { billing as billingApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import type { ApiBillingState } from '@/api/types.js';
import { onIOS } from './play.js';

/**
 * The plans, by the ids they have in App Store Connect. They are the plan
 * ids themselves (lexpad_ios `scripts/asc-products.json`), so a product maps
 * to a plan by id and no table of ours stands between them.
 */
export const STORE_PLANS = ['pro_monthly', 'pro_yearly'] as const;
export type StorePlan = (typeof STORE_PLANS)[number];

/**
 * Where a subscription bought in the App Store is changed or cancelled when
 * Apple's own sheet is not to hand: on the web, in the Android app, or when
 * the sheet cannot be shown. Apple's address, and Apple is the only seller
 * that can do either.
 */
export const APP_STORE_SUBSCRIPTIONS_URL = 'https://apps.apple.com/account/subscriptions';

/** A subscription as the App Store sells it in this Apple Account's storefront. */
export interface StoreProduct {
  id: string;
  /** Apple's localised name, from App Store Connect. */
  displayName: string;
  description: string;
  /** Apple's own formatted price, in the storefront's currency and locale. */
  displayPrice: string;
  /** The price as a decimal string, "4.99"; never a float. */
  price: string;
  currencyCode: string;
  /**
   * The locale Apple formats this storefront's prices in ("de_DE", or
   * "en_US@currency=EUR"), so a figure worked out here reads like Apple's.
   */
  priceLocale?: string;
  period: { unit: 'day' | 'week' | 'month' | 'year'; value: number };
  /** The product's introductory offer, when it has one (newer shells only). */
  introductoryOffer?: {
    displayPrice: string;
    price: string;
    paymentMode: string;
    period: { unit: 'day' | 'week' | 'month' | 'year'; value: number };
    periodCount: number;
  };
  /**
   * The product's promotional offers with Apple's own prices, when the shell
   * lists them (for people who subscribed before). Absent on older shells.
   */
  promotionalOffers?: { id: string; displayPrice: string }[];
}

/** A transaction the shell holds, as the server wants it. */
export interface StoreTransaction {
  transactionId: string;
  originalTransactionId: string;
  productId: string;
  signedTransaction: string;
}

/** The native plugin, as the web layer sees it. */
interface AppStorePlugin {
  canMakePayments(): Promise<{ allowed: boolean }>;
  products(options: { productIds: string[] }): Promise<{ products: StoreProduct[] }>;
  /**
   * Opens Apple's purchase sheet. `cancelled` is somebody backing out and
   * `pending` a purchase waiting for somebody else (Ask to Buy, a bank's
   * confirmation); neither is an error. The transaction is not finished.
   */
  purchase(options: {
    productId: string;
    appAccountToken: string;
    /** The server's signed JWS saying whether the introductory offer applies. */
    introductoryOfferEligibility?: string;
    /** A promotional offer the server signed for this purchase (a win-back). */
    promotionalOfferId?: string;
    promotionalOfferJws?: string;
  }): Promise<{
    outcome: 'purchased' | 'cancelled' | 'pending';
    transactionId?: string;
    originalTransactionId?: string;
    productId?: string;
    signedTransaction?: string;
  }>;
  finish(options: { transactionId: string }): Promise<{ finished: boolean }>;
  /** StoreKit's AppTransaction.appTransactionID (iOS 16+); newer shells only. */
  appTransactionId(): Promise<{ appTransactionId: string }>;
  unfinished(): Promise<{ transactions: StoreTransaction[] }>;
  currentEntitlements(): Promise<{ transactions: StoreTransaction[] }>;
  /** Asks the App Store again; may show the Apple Account sheet. */
  sync(): Promise<void>;
  manageSubscriptions(): Promise<void>;
  addListener(
    event: 'transaction',
    listener: (transaction: StoreTransaction) => void,
  ): Promise<{ remove: () => Promise<void> }>;
}

let plugin: Promise<{ store: AppStorePlugin }> | undefined;

/**
 * Registered on first use, and only then is Capacitor's bridge loaded, so a
 * browser never downloads it. Every entry point below checks the platform
 * first.
 *
 * The plugin comes wrapped in an object, never as a promise's value on its
 * own: Capacitor's proxy answers to every property name, `then` included,
 * so resolving a promise with it calls a native method named "then" that
 * does not exist, and the promise never settles.
 */
function appStore(): Promise<{ store: AppStorePlugin }> {
  plugin ??= import('@capacitor/core').then(({ registerPlugin }) => ({
    store: registerPlugin<AppStorePlugin>('AppStore'),
  }));
  return plugin;
}

// ---------------------------------------------------------------------------
// The account a purchase belongs to

/** Crockford's base 32, the alphabet a ULID is written in. */
const CROCKFORD = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';

/**
 * The account's public id as the UUID StoreKit carries as `appAccountToken`.
 *
 * A ULID is 128 bits written as 26 characters of Crockford base 32; the
 * UUID is the same 16 bytes written as hex, 8-4-4-4-12, lowercase. The
 * server reverses it to find the account a transaction was bought for, and
 * refuses one that names somebody else, so the two must agree to the bit.
 * Decoding is Crockford's: any case, I and L read as 1, O as 0. Anything
 * else — a missing id, a wrong length, a letter outside the alphabet, a
 * first character that would need more than 128 bits — is undefined, and a
 * purchase sheet is then not opened at all, because Apple would take the
 * money for a purchase the server cannot attribute to anyone.
 */
export function appAccountToken(publicId: string | undefined): string | undefined {
  if (publicId?.length !== 26) return undefined;
  let value = 0n;
  for (const raw of publicId.toUpperCase()) {
    const char = raw === 'I' || raw === 'L' ? '1' : raw === 'O' ? '0' : raw;
    const digit = CROCKFORD.indexOf(char);
    if (digit < 0) return undefined;
    value = (value << 5n) | BigInt(digit);
  }
  // 26 characters hold 130 bits; a ULID's first character is at most 7.
  if (value >> 128n !== 0n) return undefined;
  const hex = value.toString(16).padStart(32, '0');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

// ---------------------------------------------------------------------------
// What is on sale

/**
 * How long the plan waits for the App Store's prices. The plan is not shown
 * in the iPhone app until they arrive (a server price there would be wrong),
 * so a StoreKit that never answers must not leave Settings waiting for ever;
 * after this the paywall says Pro is not sold here, and the next look asks
 * again. StoreKit normally answers well inside a second.
 */
const STORE_PATIENCE_MS = 8000;

const giveUpAfter = (ms: number): Promise<never> =>
  new Promise((_, reject) => {
    setTimeout(() => {
      reject(new Error('timeout'));
    }, ms);
  });

let products: Promise<StoreProduct[]> | undefined;
let loaded: StoreProduct[] = [];

/**
 * Lexpad Pro's subscriptions as the App Store sells them to this Apple
 * Account, asked once and kept for the run of the app. These are the only
 * prices the paywall shows in the iPhone app.
 *
 * Empty off iOS, when this Apple Account may not pay (Screen Time), and on
 * any failure: a price we are not sure of is worse than no offer. A failure
 * is not kept, so the next look asks again.
 */
export function loadStoreProducts(): Promise<StoreProduct[]> {
  if (!onIOS()) return Promise.resolve([]);
  const ask = async (): Promise<StoreProduct[]> => {
    const { store } = await appStore();
    const { allowed } = await store.canMakePayments();
    if (!allowed) return [];
    const answer = await store.products({ productIds: [...STORE_PLANS] });
    return answer.products.filter((one) => (STORE_PLANS as readonly string[]).includes(one.id));
  };
  products ??= Promise.race([ask(), giveUpAfter(STORE_PATIENCE_MS)])
    .then((found) => {
      loaded = found;
      if (found.length === 0) products = undefined;
      return found;
    })
    .catch(() => {
      products = undefined;
      return [];
    });
  return products;
}

/** The products the last successful look found, for a caller that cannot wait. */
export function storeProductsNow(): StoreProduct[] {
  return loaded;
}

/** Forgets the products, so a test starts from nothing. Tests only. */
export function forgetStoreProducts(): void {
  products = undefined;
  loaded = [];
  plugin = undefined;
}

// ---------------------------------------------------------------------------
// Buying

/** What a purchase attempt ended as. */
export type Outcome =
  | { kind: 'bought'; transactionId: string; signedTransaction: string | undefined }
  | { kind: 'closed' }
  | { kind: 'pending' };

/**
 * Opens Apple's sheet for one plan, with the account attached. Throws when
 * the account cannot be attached (the sheet is then not opened) and when
 * StoreKit refuses; backing out is `closed`, and waiting for a parent or a
 * bank is `pending`, which arrives later through `listenForTransactions`.
 */
export async function buyOnAppStore(
  plan: StorePlan,
  accountId: string | undefined,
  terms: AppleTerms,
): Promise<Outcome> {
  const token = appAccountToken(accountId);
  if (token === undefined) throw new Error('bad_account');
  // Without the server's word on the introductory offer, Apple would give it
  // to anybody new to the subscription: no sheet without it.
  if (terms.eligibility === '') throw new Error('no_eligibility');
  const result = await (
    await appStore()
  ).store.purchase({
    productId: plan,
    appAccountToken: token,
    introductoryOfferEligibility: terms.eligibility,
    ...(terms.promotional === undefined
      ? {}
      : { promotionalOfferId: terms.promotional.offerId, promotionalOfferJws: terms.promotional.jws }),
  });
  if (result.outcome === 'pending') return { kind: 'pending' };
  if (result.outcome !== 'purchased') return { kind: 'closed' };
  if (result.transactionId === undefined || result.transactionId === '') throw new Error('no_transaction');
  return { kind: 'bought', transactionId: result.transactionId, signedTransaction: result.signedTransaction };
}

/**
 * Asks the server for the purchase's signed eligibility JWS, which every
 * App Store purchase carries: it switches the product's introductory offer
 * on for an account whose offer is open (`offerId`) and off for everybody
 * else. Apple applies an introductory offer to anybody new to the
 * subscription group unless told otherwise, so a purchase without this JWS
 * would hand the offer price to people the server never chose. Throws, and
 * no sheet is opened, when the shell cannot give StoreKit's app transaction
 * id (an older shell), the server refuses (`offer_closed` among them), or
 * its answer is not a JWS for this plan: fail closed.
 */
/** What the server signed for one App Store purchase. */
export interface AppleTerms {
  /** The introductory-offer eligibility JWS; every purchase carries one. */
  eligibility: string;
  /** A promotional offer (somebody who subscribed through Apple before). */
  promotional?: { offerId: string; jws: string } | undefined;
}

export async function appStoreEligibility(plan: StorePlan, offerId: string | undefined): Promise<AppleTerms> {
  const { store } = await appStore();
  let appTransactionId: unknown;
  try {
    ({ appTransactionId } = await store.appTransactionId());
  } catch (cause) {
    // AppTransaction needs iOS 16; the shell says `unavailable` before it.
    if ((cause as { code?: unknown } | null)?.code === 'unavailable')
      throw new Error('ios_too_old', { cause });
    throw new Error('no_app_transaction', { cause });
  }
  if (typeof appTransactionId !== 'string' || !/^[0-9]{1,32}$/.test(appTransactionId)) {
    throw new Error('no_app_transaction');
  }
  const checkout = await billingApi.checkout(plan, { offerId, appTransactionId });
  const jws = checkout.apple?.introductoryOfferEligibility;
  if (
    checkout.provider !== 'apple' ||
    checkout.apple?.productId !== plan ||
    jws === undefined ||
    jws === ''
  ) {
    throw new Error('no_eligibility');
  }
  const promo = checkout.apple.promotionalOffer;
  return {
    eligibility: jws,
    ...(promo !== undefined && promo.offerId !== '' && promo.jws !== '' ? { promotional: promo } : {}),
  };
}

/**
 * Apple's own price for an offer on a product: the named promotional offer,
 * or the introductory offer when none is named. Undefined when StoreKit has
 * none, and the offer is then not shown in the iPhone app.
 */
export function appStoreIntroPrice(productId: string, promotionalOfferId?: string): string | undefined {
  const product = loaded.find((one) => one.id === productId);
  const price =
    promotionalOfferId === undefined
      ? product?.introductoryOffer?.displayPrice
      : product?.promotionalOffers?.find((one) => one.id === promotionalOfferId)?.displayPrice;
  return price === undefined || price === '' ? undefined : price;
}

/**
 * Tells Apple the purchase has been delivered. Called only after the server
 * has answered 200 for it. A failure is not worth reporting: the
 * transaction stays unfinished, is sent again next time, and the server's
 * answer to a second look is the same plan.
 */
export async function finishTransaction(transactionId: string): Promise<boolean> {
  if (!onIOS()) return false;
  try {
    const { finished } = await (await appStore()).store.finish({ transactionId });
    return finished;
  } catch {
    return false;
  }
}

/** Whether a failure is the server saying the purchase is another account's. */
export function notYours(cause: unknown): boolean {
  return isApiError(cause, 'forbidden') && cause.code === 'purchase_not_yours';
}

/**
 * Sends one transaction to the server and finishes it when the server
 * agrees. Answers the plan, or throws what the server said, leaving the
 * transaction unfinished for next time.
 */
export async function settle(transaction: StoreTransaction): Promise<ApiBillingState> {
  const plan = await billingApi.verifyApplePurchase({
    transactionId: transaction.transactionId,
    signedTransaction: transaction.signedTransaction,
  });
  await finishTransaction(transaction.transactionId);
  return plan;
}

// ---------------------------------------------------------------------------
// Restoring

/** What a restore found. */
export type RestoreResult =
  /** At least one purchase the server accepted; the plan it answered last. */
  | { kind: 'restored'; state: ApiBillingState }
  /** This Apple Account holds nothing to restore. */
  | { kind: 'nothing' }
  /** What it holds was bought for another Lexpad account. */
  | { kind: 'notYours' }
  /** Somebody closed the Apple Account sheet. */
  | { kind: 'cancelled' }
  /** The App Store or the server could not be reached. */
  | { kind: 'failed' };

/**
 * Sends every subscription this Apple Account holds to the server: the
 * unfinished transactions and the current entitlements, each once. Each one
 * the server accepts is finished; one it refuses — another account's, or a
 * server that cannot reach Apple right now — stays unfinished for the next
 * try.
 *
 * `sync` first asks the App Store again, which can show the Apple Account
 * sheet, so it is only for a "Restore purchases" tap. The quiet restore
 * when the plan opens reads what the device already knows.
 */
export async function restoreAppStore({ sync }: { sync: boolean }): Promise<RestoreResult> {
  if (!onIOS()) return { kind: 'nothing' };
  let store: AppStorePlugin;
  try {
    ({ store } = await appStore());
  } catch {
    return { kind: 'failed' };
  }
  let trouble = false;
  if (sync) {
    try {
      await store.sync();
    } catch (cause) {
      if ((cause as { code?: unknown } | null)?.code === 'cancelled') return { kind: 'cancelled' };
      // The App Store could not be reached; what the device already holds
      // is still worth sending.
      trouble = true;
    }
  }
  const held = new Map<string, StoreTransaction>();
  for (const read of [() => store.unfinished(), () => store.currentEntitlements()]) {
    try {
      for (const one of (await read()).transactions) {
        if (!held.has(one.transactionId)) held.set(one.transactionId, one);
      }
    } catch {
      trouble = true;
    }
  }
  if (held.size === 0) return trouble ? { kind: 'failed' } : { kind: 'nothing' };

  let restored: ApiBillingState | undefined;
  let refused = false;
  for (const transaction of held.values()) {
    try {
      // The answer is the plan itself, so the last one to arrive is it.
      restored = await settle(transaction);
    } catch (cause) {
      if (notYours(cause)) refused = true;
      else trouble = true;
    }
  }
  if (restored !== undefined) return { kind: 'restored', state: restored };
  if (refused) return { kind: 'notYours' };
  return trouble ? { kind: 'failed' } : { kind: 'nothing' };
}

// ---------------------------------------------------------------------------
// What arrives on its own

let listening: Promise<{ remove: () => Promise<void> } | undefined> | undefined;
let onPlan: ((state: ApiBillingState) => void) | undefined;

/**
 * Listens for transactions that did not come out of a purchase sheet: a
 * renewal, an Ask to Buy a parent approved, a purchase on another device
 * with the same Apple Account, and the unfinished ones from an earlier
 * launch, which StoreKit hands back as the app starts. Each goes to the
 * server and is finished once it agrees; the plan it answers is handed to
 * `plan`.
 *
 * One subscription for the app, however often this is called; the last
 * caller's `plan` is the one told. Returns a stop, for signing out: a
 * transaction that arrives signed out stays unfinished until somebody signs
 * in.
 */
export function listenForTransactions(plan: (state: ApiBillingState) => void): () => void {
  if (!onIOS()) return () => undefined;
  onPlan = plan;
  listening ??= appStore()
    .then(({ store }) =>
      store.addListener('transaction', (transaction) => {
        settle(transaction)
          .then((state) => {
            onPlan?.(state);
          })
          .catch(() => {
            // Refused or out of reach: it stays unfinished, and StoreKit
            // offers it again at the next launch.
          });
      }),
    )
    .catch(() => undefined);
  return () => {
    onPlan = undefined;
    const handle = listening;
    listening = undefined;
    void handle?.then((one) => one?.remove()).catch(() => undefined);
  };
}

// ---------------------------------------------------------------------------
// Managing

/**
 * Where a subscription bought in the App Store is changed or cancelled.
 * Inside the iPhone app, Apple's own sheet over the app (the shell falls
 * back to the App Store page itself); anywhere else, the App Store's
 * subscriptions page in a new tab, because Apple is the only seller that can
 * do either.
 */
export async function manageAppStoreSubscription(): Promise<void> {
  if (onIOS()) {
    try {
      await (await appStore()).store.manageSubscriptions();
      return;
    } catch {
      // Fall through to Apple's page.
    }
  }
  window.open(APP_STORE_SUBSCRIPTIONS_URL, '_blank', 'noopener,noreferrer');
}
